fn decode_cyclic(s: &Vec<i8>) -> Vec<i8> {
    let mut res = Vec::with_capacity(s.len());

    // Process each full chunk of 3 elements by rotating it right by one:
    // [a, b, c] -> [c, a, b]
    for chunk in s.chunks(3) {
        match chunk {
            [a, b, c] => {
                res.push(*c);
                res.push(*a);
                res.push(*b);
            }
            // For the tail of length < 3, just copy as‐is.
            _ => res.extend_from_slice(chunk),
        }
    }

    res
}

